INSERT INTO online_shop.product (name, jyoutai, description, price, stock, maker_id, category_id, image_url) VALUES

('オート調光バックミラー', '新品', '後続車のヘッドライトによる眩しさを自動で調整するオート調光バックミラーです。夜間や長距離運転時のドライバーの目の疲労を軽減し、快適で安全なドライブをサポートします。反射率の自動調整機能により、昼夜問わずクリアな後方視界を確保します。取り付けも簡単で、多くの車種に対応しており、既存ミラーと交換するだけで高機能を追加可能です。外観もスマートで、車内インテリアと調和するデザインです。', 15000.00, 5, 20, 9, NULL),

('フットランプLED', '新品', '車内フロアを幻想的に彩るフットランプLEDです。多彩なカラー表示が可能で、夜間の運転でも視認性を確保しつつおしゃれな空間を演出。省エネ設計で長寿命、取り付けも簡単。車内のインテリアをワンランクアップさせ、ドライブをより快適で楽しいものにします。', 3500.00, 15, 9, 16, NULL),

('ブルーミラータイプサイドミラー', '新品', '眩しい光を軽減するブルーミラー仕様のサイドミラーです。日中の太陽光や夜間の対向車ライトの眩しさを抑え、ドライバーの視認性を大幅に向上させます。耐久性にも優れており、長期間の使用でも曇りや変色が少なく、安心して使用できます。取り付けも簡単で、多くの車種に対応可能。運転中の目の疲労を軽減し、快適なドライブ環境を提供するための必須アイテムです。', 8000.00, 15, 12, 9, 'https://t3.ftcdn.net/jpg/17/03/60/46/240_F_1703604611_fLQG6rMrIJZpWj0hfExKfKBo4b3b5GsC.jpg'),

('ドアウェルカムLED', '新品', 'ドアを開けると点灯するウェルカムLEDライトです。夜間や暗所での乗降時の安全性を向上させるだけでなく、車内外のインテリアをスタイリッシュに演出します。省エネで長寿命、取り付けも容易。さりげなく車の個性を演出する便利なアイテムです。', 4000.00, 10, 5, 16, NULL),

('ポータブルカーオーディオ', '新品', '簡単に取り付け可能なポータブルカーオーディオ。USBやBluetoothでスマートフォン接続可能で、高音質再生が可能です。小型ながら迫力ある音響を提供し、日常のドライブからレジャーまで幅広く活躍します。電源はシガーソケットから供給可能で、設置場所の自由度も高く、手軽に音楽環境を整えることができます。', 8000.00, 20, 11, 11, NULL),

('折りたたみ式ドリンクホルダー', '新品', '使用しないときは折りたためる省スペース設計のドリンクホルダーです。軽量で取り付けも簡単、車内の空間を有効活用可能。安定性にも優れており、走行中のこぼれや振動を防止します。ペットボトルやカップに対応し、日常ドライブから長距離運転まで快適に使用できます。', 1800.00, 25, 9, 17, 'https://t3.ftcdn.net/jpg/03/81/85/56/240_F_381855622_mUAOXzdddn5aMghzSSbX507WBG3NuRcX.jpg'),

('ステレオパワーアンプ', '新品', '高性能ステレオパワーアンプで、クリアで迫力ある音楽再生を実現。コンパクト設計で車内のスペースを有効活用でき、設置も容易です。耐久性に優れ、長時間使用しても音質が安定。音質調整機能も豊富で、低音から高音までバランスよく再生可能。音楽好きのドライバーに最適なモデルです。', 27000.00, 5, 7, 13, NULL),

('ハイブリッドワイパー', '新品', '雨や雪に強いハイブリッドワイパーです。フレームレス設計によりガラス面に均一に接触し、拭きムラを防止します。静音設計で走行中の騒音を抑え、快適な運転環境を提供。耐久性にも優れており、長期間使用可能で、雨天や雪道での視界確保に最適です。取り付けも簡単で、ほとんどの車種に対応可能。ドライバーの安全運転を強力にサポートするアイテムです。', 3000.00, 18, 14, 10, NULL),

('折りたたみ式タイヤチェーン', '新品', '雪道や凍結路面での安全走行を支援する折りたたみ式タイヤチェーンです。コンパクトに収納可能で持ち運びも簡単。耐久性の高い素材で長期間使用可能、滑りにくい設計で安心の冬季ドライブをサポートします。', 13000.00, 10, 10, 15, 'https://t4.ftcdn.net/jpg/16/95/57/87/240_F_1695578740_K7uloJ5IefkPPsSPJVbvc5ywRIij33RQ.jpg'),

('ハイレゾ対応カーオーディオ', '新品', 'ハイレゾ音源対応の高音質カーオーディオです。CDやUSB再生に加え、高解像度音源の再生も可能で、車内でクリアで迫力ある音楽体験を提供します。音質調整機能も搭載され、低音から高音までバランスよく再生可能。音楽好きのドライバーに最適なモデルで、長距離ドライブも快適に楽しめます。', 25000.00, 8, 15, 11, NULL),

('ヒーター付きサイドミラー', '新品', '寒冷地での使用に最適なヒーター付きサイドミラーです。霜や雪の付着を防ぎ、冬季の視界を確保することができます。電動格納機能も搭載しており、利便性と安全性を兼ね備えています。高耐久素材を使用し、長期間の使用でも変形や故障の心配が少ない設計です。さらにスタイリッシュなデザインで、車両の外観を損なわず、ドライバーの運転体験をより快適にします。冬季ドライブでの安心感を大幅に向上させるモデルです。', 14000.00, 8, 6, 9, NULL),

('コンポーネントスピーカー', '新品', '高音質コンポーネントスピーカーで、クリアな中高音と迫力ある低音を実現。専用のツィーターとミッドレンジユニットで音の広がりを確保し、車内での音楽体験を劇的に向上させます。取り付けも柔軟で、多くの車種に対応可能。耐久性に優れ、長期間使用しても音質が劣化しにくい設計。音楽好きのドライバーに最適なモデルです。', 15000.00, 8, 12, 12, NULL),

('フルHD前方録画ドライブレコーダー', '新品', 'フルHD画質対応のドライブレコーダーで、前方視界を鮮明に録画します。高感度カメラを搭載しているため、夜間やトンネル内でもくっきりと映像を記録可能です。衝撃検知機能や自動録画機能も備えており、事故やトラブルの際の証拠として活用できます。コンパクトで取り付けも簡単、運転中に邪魔にならない設計です。安全運転のサポートだけでなく、万が一のトラブル対応にも安心の一台です。', 9800.00, 15, 4, 2, 'https://t4.ftcdn.net/jpg/04/08/17/45/240_F_408174543_2hCxdEoGB4GHAgNcyQvobMvniJt2ZcWR.jpg'),

('ハロゲン高輝度ヘッドライト', '新品', 'コストパフォーマンスに優れた高輝度ハロゲンヘッドライト。従来型に比べて明るさが増しており、夜間や早朝の運転でも視界を確保できます。長寿命設計で交換の手間が少なく、定期的なメンテナンスも簡単。取り付けも容易で、多くの車種に対応可能です。価格が手頃でありながら性能は十分で、初心者ドライバーからベテランまで幅広く利用できる安心の製品です。', 9000.00, 10, 5, 7, NULL),

('中古HIDヘッドライト', '中古', '中古ながらも十分に使えるHIDヘッドライト。従来のハロゲンより明るく、夜間ドライブの安全性を大幅に向上させます。取り外し後の検品をクリアしており、動作に問題はありません。価格を抑えつつも視認性を確保したい方に最適です。夜間の安全運転を支えるアイテムとして、コストを重視するユーザーに特におすすめの中古モデルです。', 7000.00, 5, 6, 7, 'https://t4.ftcdn.net/jpg/16/63/90/45/240_F_1663904500_DmkqIM2oXCjzrhaTyAiepejoOW7GMKQ9.jpg'),

('多機能カークリーナーセット', '新品', '車内外の掃除に便利な多機能カークリーナーセット。ブラシ、クロス、液剤がセットになっており、ホコリや泥汚れを効率的に除去可能です。コンパクトで持ち運びやすく、家庭用にも利用可能。シートやフロアマット、ダッシュボードまで幅広く使えます。プロ仕様の性能を家庭でも発揮できる優れもの。常に車を清潔に保ちたい方にとって必需品のセットです。', 3500.00, 20, 7, 8, 'https://t3.ftcdn.net/jpg/15/47/50/66/240_F_1547506689_nynmiE6fEGLuTsBs1eWabq9B6uHiffEJ.jpg'),

('吸引力強化ハンディ掃除機', '新品', '強力な吸引力を備えた車載用ハンディ掃除機。小型ながらパワフルで、シートの隙間やマットの奥に入り込んだホコリまでしっかり吸引します。軽量設計で女性でも扱いやすく、持ち運びも簡単。充電式でコードレス仕様のため、車内のどこでも自由に使用可能です。日常的な掃除から長距離ドライブ後の清掃まで、幅広く活躍する頼れるアイテムです。', 4200.00, 15, 6, 8, NULL),

('中古カークリーナーセット', '中古', '中古品ですが十分に使えるカークリーナーとブラシのセット。日常の簡単な掃除やサブ用として便利に利用可能です。新品に比べて価格が抑えられており、コスト重視のユーザーに最適。シートやマットの表面汚れの除去には十分な性能を発揮し、定期的な清掃にも問題なく使用できます。手軽に車内をきれいに保ちたい方にとって、コスパに優れた実用的な選択肢です。', 1800.00, 8, 5, 8, NULL),

('360度回転式車載スマホホルダー', '新品', '360度回転可能な車載スマホホルダーです。運転中のナビアプリや通話、動画視聴に便利で、車内のエアコン吹き出し口に簡単取り付けできます。角度調整も自由にでき、iPhoneやAndroidなど幅広い機種に対応。しっかり固定できるので走行中の振動や揺れにも耐え、安心して使用可能です。コンパクト設計で視界を妨げず、長時間の運転でも快適に利用できます。', 1200.00, 50, 12, 3, NULL),

('地図更新無料カーナビゲーション', '新品', '最新地図データの更新が無料で提供されるカーナビゲーションです。7インチ液晶で画面が広く、交差点や曲がり角もはっきり表示されるため運転中の安心感が高まります。Bluetooth対応でスマホとの連携も可能。音声案内やルート検索もスムーズで、長距離ドライブや初めての道でも迷わず目的地へ到着できます。安全性と利便性を両立させた多機能モデルです。', 50000.00, 4, 8, 1, NULL),

('Bluetooth対応カーナビゲーション', '新品', 'スマートフォンと簡単にBluetooth接続できるカーナビです。音声案内機能付きで運転中もハンズフリーで操作可能。ルート検索や目的地設定がスムーズで、渋滞情報やリアルタイム交通情報にも対応しています。7インチの液晶画面は視認性が高く、運転中のストレスを軽減。地図更新も無料で提供されるため、長期利用でも安心です。初心者からベテランドライバーまで使いやすい設計になっています。', 42000.00, 6, 21, 1, 'https://t3.ftcdn.net/jpg/03/01/13/68/240_F_301136861_yoLU3TmRwOcXcPtbBdUzCFPNZ0ugDFl1.jpg'),

('前後2カメラ搭載ドライブレコーダー', '新品', '前後2カメラ搭載のドライブレコーダーです。前方と後方の両方を録画できるため、事故や接触時の証拠映像として非常に有用です。駐車監視や衝撃検知機能も備え、駐車中のトラブルや当て逃げにも対応可能。夜間映像も鮮明で、車両周辺の状況をしっかり記録します。設置も簡単で、運転中に視界を妨げず安心して使用できます。安全性と利便性を兼ね備えた高性能モデルです。', 15000.00, 10, 5, 2, NULL),

('2DINカーオーディオプレーヤー', '新品', 'CD/USB/Bluetooth対応の2DINカーオーディオです。高音質再生を実現し、ドライブ中の音楽体験を快適にします。スマホとの接続も簡単で、ナビや通話、音楽再生をスムーズに操作可能です。さらに直感的な操作画面で、目的の機能に素早くアクセス可能。ドライブをより快適にする多機能オーディオとして、日常利用から長距離運転まで幅広く活躍します。', 15000.00, 12, 6, 11, NULL),

('ウォッシャータンク補充液', '新品', '車用ウォッシャー液です。フロントガラスのホコリや油膜をしっかり除去し、雨天や汚れた路面でもクリアな視界を確保します。長距離運転や日常走行時の視認性を向上させ、安全運転を支援します。車内から簡単に補充でき、保管も便利。さらに、環境に配慮した成分を使用しており、安心して使用可能です。', 800.00, 50, 2, 10, 'https://t4.ftcdn.net/jpg/06/68/81/43/240_F_668814388_TUlI6RqSWej7g3OvQlU0UErkqV07z3hU.jpg'),

('金属製スタッドレスタイヤチェーン', '新品', '耐久性に優れた金属製スタッドレスタイヤチェーンです。雪道や凍結路面でも高いグリップ力を発揮し、安全性を確保。取り付けも比較的簡単で、多くの車種に対応可能。長期間の使用にも耐える設計で、冬季ドライブを安心して楽しめます。雪道走行時の滑りやすさを大幅に軽減する必須アイテムです。', 18000.00, 5, 15, 15, 'https://t4.ftcdn.net/jpg/16/69/59/37/240_F_1669593783_xav8Chqf6uCy8MElx9hT7cevh7VtdgdH.jpg'),

('耐久性ラバーフロアマット', '新品', '耐久性に優れたラバー製フロアマットです。汚れや水分をしっかり防ぎ、日常のメンテナンスが簡単。滑り止め加工により、安全性も確保。車内のフロアを清潔に保ち、長期間使用可能です。取り付けも簡単で、多くの車種に対応。雨天や雪道でも安心して使用できる必須アイテムです。', 4500.00, 20, 8, 18, NULL),

('LEDルームランプセット', '新品', '車内の照明を明るく演出するLEDルームランプセットです。省エネで長寿命、取り付けも簡単で、多くの車種に対応。夜間や暗所でも車内を快適に照らし、視認性と安全性を向上させます。さらに高輝度LEDにより、インテリアの雰囲気もアップ。長時間の運転でも快適な車内空間を提供します。', 5000.00, 20, 6, 16, NULL),

('コンパクトカーアンプ', '新品', '小型ながら高出力を実現したコンパクトカーアンプです。スピーカーの性能を最大限に引き出し、クリアで迫力ある音質を提供します。取り付けも簡単で、多くの車種に対応可能。長時間使用しても熱による劣化が少なく、安定した性能を維持。音質調整機能も搭載されており、低音から高音までバランスよく調整可能。ドライブ中の音楽体験を快適にします。', 18000.00, 12, 9, 13, NULL),

('高性能エンジンオイル', '新品', '高性能合成エンジンオイルです。エンジン内部の摩擦を大幅に低減し、燃費性能と耐久性を向上させます。長期間使用しても劣化が少なく、エンジンのパフォーマンスを安定して維持可能です。冷却性能も高く、夏季・冬季問わず安定した動作を提供。日常の通勤から長距離ドライブまで、車両のエンジンを保護し、寿命を延ばす必須アイテムです。', 5000.00, 30, 2, 14, 'https://t4.ftcdn.net/jpg/15/32/42/59/240_F_1532425933_iFftu7ektiOjcGazZ2GY8cO81rAZFVcR.jpg'),

('カスタムカーペットマット', '新品', '車内に高級感を演出するカスタムカーペットマットです。耐久性に優れ、汚れや摩耗に強く、長期間使用可能。専用設計により車種にフィットし、ズレや巻き込みを防止。手入れも簡単で、日常の掃除やメンテナンスも容易です。快適で清潔な車内空間を提供する必須アイテムです。', 6000.00, 15, 12, 18, NULL),

('撥水ワイパーブレードセット', '新品', '撥水加工が施されたワイパーブレードで、雨天時でもフロントガラスをクリアに保ちます。耐久性に優れ、摩耗や劣化が少なく、長期間安定した拭き取り性能を維持可能です。シートやワイパーアームへの装着も簡単で、ドライバーの手間を大幅に削減。雨天時の視界を確保し、安全運転をサポートする便利なセットです。さらに、静音設計により拭き取り時の雑音も抑えられ、快適な運転環境を提供します。', 2500.00, 25, 5, 10, NULL),

('大型パワードサブウーファー', '新品', '低音域を重視した大型パワードサブウーファーです。迫力ある低音でドライブ中の音楽体験を大幅に向上。内蔵アンプにより接続も簡単で、設置後すぐに高音質再生が可能です。耐久性にも優れ、長時間の使用でも安定した音質を提供。車内での音響バランスを整え、音楽の臨場感を高める必須アイテムです。', 22000.00, 5, 14, 12, NULL),

('駐車監視機能付き高性能ドライブレコーダー', '新品', '駐車監視機能を備えた高性能ドライブレコーダーです。車両が駐車中でも衝撃を感知すると自動で録画を開始し、事故や盗難の証拠映像として活用できます。フルHD画質で映像は鮮明、前方視界も広く安全運転をサポート。取り付けも簡単で、初心者でも安心して使用可能です。夜間や暗所でも高感度カメラでしっかり撮影でき、万が一のトラブルにも備えられる安心設計です。', 20000.00, 5, 16, 2, 'https://t3.ftcdn.net/jpg/04/51/12/56/240_F_451125645_FrQcXtVqhPh0d92a6LYxDop9k0YQL78y.jpg'),

('エアコン吹き出し口対応スマホスタンド', '新品', 'エアコン吹き出し口に簡単に取り付け可能なスマホスタンドです。360度回転と角度調整機能付きで、運転中でも画面が見やすく操作もスムーズ。iPhoneやAndroidなど様々なスマートフォンに対応しており、ナビアプリや動画視聴にも最適。安定した固定力で走行中の振動に強く、長距離ドライブでも安心。コンパクトながら使いやすさを追求した車載アクセサリーです。', 1800.00, 30, 19, 3, NULL),

('中古エアコン取付スマホホルダー', '中古', 'エアコン吹き出し口タイプのスマホホルダー。中古ですが状態良好で、運転中のナビ利用や通話に便利。iPhoneやAndroidなど幅広いスマートフォンに対応しています。', 1500.00, 20, 15, 3, 'https://t3.ftcdn.net/jpg/16/18/02/46/240_F_1618024690_VyafZUPfqLTCH19ZypCBil5xW5ZgYqki.jpg'),

('7インチワイド液晶カーナビゲーション', '新品', '7インチのワイド液晶を搭載したカーナビゲーションです。大画面で地図が見やすく、運転中も視認性が高いため安全運転をサポートします。Bluetooth対応でスマートフォンと接続すれば音楽再生や通話も可能。さらに最新地図の更新が無料で提供されるため、常に正確なルート案内を受けられます。長距離ドライブから日常の買い物まで、幅広い用途に活用できる便利な一台です。', 35000.00, 8, 27, 1, 'https://t4.ftcdn.net/jpg/06/13/33/59/240_F_613335941_P2VoWdeKA9bDrv5Nk7Z5Ib0bTHyzVOCQ.jpg'),

('高感度ナイトビジョンドライブレコーダー', '中古', '暗所でも高精細に録画可能なナイトビジョン対応ドライブレコーダーです。フルHD画質で夜間走行時も視認性が高く、事故時の証拠映像として信頼性抜群。衝撃検知、駐車監視、自動録画機能を搭載し、初心者でも安心して使用可能。コンパクト設計で車内の邪魔にならず、最新の安全運転サポートを提供します。', 22000.00, 7, 9, 2, 'https://t4.ftcdn.net/jpg/05/16/73/63/240_F_516736393_j83WPUifUN03tMAcOc5QDqCLTbwAZHm3.jpg'),

('折りたたみ式ドリンクホルダー', '新品', '使用しないときは折りたためる省スペース設計のドリンクホルダーです。軽量で取り付けも簡単、車内の空間を有効活用可能。安定性にも優れており、走行中のこぼれや振動を防止します。ペットボトルやカップに対応し、日常ドライブから長距離運転まで快適に使用できます。', 1800.00, 25, 9, 17, NULL),

('オート調光バックミラー', '新品', '後続車のヘッドライトによる眩しさを自動で調整するオート調光バックミラーです。夜間や長距離運転時のドライバーの目の疲労を軽減し、快適で安全なドライブをサポートします。反射率の自動調整機能により、昼夜問わずクリアな後方視界を確保します。取り付けも簡単で、多くの車種に対応しており、既存ミラーと交換するだけで高機能を追加可能です。外観もスマートで、車内インテリアと調和するデザインです。', 15000.00, 5, 20, 9, 'https://t3.ftcdn.net/jpg/16/79/82/28/240_F_1679822807_tsuoUwcTAbpJ93EmBoOtZEeghu3A90wL.jpg'),

('ヒーター付きサイドミラー', '新品', '寒冷地での使用に最適なヒーター付きサイドミラーです。霜や雪の付着を防ぎ、冬季の視界を確保することができます。電動格納機能も搭載しており、利便性と安全性を兼ね備えています。高耐久素材を使用し、長期間の使用でも変形や故障の心配が少ない設計です。さらにスタイリッシュなデザインで、車両の外観を損なわず、ドライバーの運転体験をより快適にします。冬季ドライブでの安心感を大幅に向上させるモデルです。', 14000.00, 8, 6, 9, NULL),

('ブルーミラータイプサイドミラー', '新品', '眩しい光を軽減するブルーミラー仕様のサイドミラーです。日中の太陽光や夜間の対向車ライトの眩しさを抑え、ドライバーの視認性を大幅に向上させます。耐久性にも優れており、長期間の使用でも曇りや変色が少なく、安心して使用できます。取り付けも簡単で、多くの車種に対応可能。運転中の目の疲労を軽減し、快適なドライブ環境を提供するための必須アイテムです。', 8000.00, 15, 12, 9, 'https://t3.ftcdn.net/jpg/13/57/31/54/240_F_1357315405_gOxGBb1BBdi04m8YAkkBtQcNg4nLSPhL.jpg'),

('フラットワイパーブレードセット', '新品', '最新設計のフラットワイパーブレードで、ガラス面に均一に接触し拭きムラを防ぎます。耐摩耗性に優れ、長期間安定した性能を発揮。雨や雪、霧の日でも視界を確保し、安全運転を支援します。取り付けも簡単で、多くの車種に対応。静音性も高く、拭き取り時の不快な音を抑え、快適なドライブを提供する優れたワイパーブレードです。', 2800.00, 20, 10, 10, 'https://t4.ftcdn.net/jpg/01/77/13/49/240_F_177134971_NxeVm7qmpMsb71msh0WYDgAbw6Cmu5k8.jpg'),

('ハイブリッドワイパー', '新品', '雨や雪に強いハイブリッドワイパーです。フレームレス設計によりガラス面に均一に接触し、拭きムラを防止します。静音設計で走行中の騒音を抑え、快適な運転環境を提供。耐久性にも優れており、長期間使用可能で、雨天や雪道での視界確保に最適です。取り付けも簡単で、ほとんどの車種に対応可能。ドライバーの安全運転を強力にサポートするアイテムです。', 3000.00, 18, 14, 10, 'https://t4.ftcdn.net/jpg/06/11/98/41/240_F_611984118_BSEvHTo5dOV0gZeX2YhRKDFwHhW6MB45.jpg'),

('ポータブルカーオーディオ', '新品', '簡単に取り付け可能なポータブルカーオーディオ。USBやBluetoothでスマートフォン接続可能で、高音質再生が可能です。小型ながら迫力ある音響を提供し、日常のドライブからレジャーまで幅広く活躍します。電源はシガーソケットから供給可能で、設置場所の自由度も高く、手軽に音楽環境を整えることができます。', 8000.00, 20, 11, 11, NULL),

('タッチスクリーンオーディオ', '新品', '大型タッチスクリーンを搭載したカーオーディオです。地図表示や音楽再生などの操作が直感的に可能で、運転中のストレスを軽減します。Bluetooth接続やスマホ連携にも対応し、通話や音楽再生もスムーズ。高解像度ディスプレイで視認性も高く、車内の利便性を大幅に向上させます。', 20000.00, 10, 9, 11, 'https://t3.ftcdn.net/jpg/06/13/88/30/240_F_613883029_5u1V6cfX8L0m8AvWSUkzhHfoqoYeQhP8.jpg'),

('ハイレゾ対応カーオーディオ', '新品', 'ハイレゾ音源対応の高音質カーオーディオです。CDやUSB再生に加え、高解像度音源の再生も可能で、車内でクリアで迫力ある音楽体験を提供します。音質調整機能も搭載され、低音から高音までバランスよく再生可能。音楽好きのドライバーに最適なモデルで、長距離ドライブも快適に楽しめます。', 25000.00, 8, 15, 11, NULL),

('高音質カースピーカーセット', '新品', 'フロント・リア対応の高音質カースピーカーセットです。クリアで迫力ある音質を再現し、ドライブ中の音楽体験を大幅に向上させます。耐久性に優れた素材を使用しており、長期間の使用でも劣化しにくい設計です。取り付けも簡単で、多くの車種に対応可能。音域のバランスも優れており、低音から高音まで幅広く再現。車内での音楽体験をより臨場感あふれるものにします。', 12000.00, 10, 7, 12, 'https://stock.adobe.com/v1/pics/placeholders/spacer.gif'),

('防水カースピーカー', '新品', '雨や湿気に強い防水仕様のカースピーカーです。耐久性が高く、車内外の温度変化や湿度にも強いため、長期間安定した音質を維持可能です。取り付けも簡単で、フロント・リア両方に対応。高音質再生と耐久性を両立しており、アウトドアや長距離ドライブでも安心して使用できます。車内の音響環境を大幅に向上させる必須アイテムです。', 8500.00, 15, 5, 12, 'https://t4.ftcdn.net/jpg/06/13/88/55/240_F_613885565_p4zlGeYPQk3KVtdkaYpNwpvauOUQMnAf.jpg'),

('コンポーネントスピーカー', '新品', '高音質コンポーネントスピーカーで、クリアな中高音と迫力ある低音を実現。専用のツィーターとミッドレンジユニットで音の広がりを確保し、車内での音楽体験を劇的に向上させます。取り付けも柔軟で、多くの車種に対応可能。耐久性に優れ、長期間使用しても音質が劣化しにくい設計。音楽好きのドライバーに最適なモデルです。', 15000.00, 8, 12, 12, NULL),

('ステレオパワーアンプ', '新品', '高性能ステレオパワーアンプで、クリアで迫力ある音楽再生を実現。コンパクト設計で車内のスペースを有効活用でき、設置も容易です。耐久性に優れ、長時間使用しても音質が安定。音質調整機能も豊富で、低音から高音までバランスよく再生可能。音楽好きのドライバーに最適なモデルです。', 27000.00, 5, 7, 13, NULL),

('高出力モノラルアンプ', '新品', '大型サブウーファー用の高出力モノラルアンプです。迫力ある低音を実現し、音楽体験を劇的に向上させます。耐久性に優れ、長時間の使用でも安定した性能を提供。コンパクト設計で車内のスペースを有効活用可能。音質調整も可能で、車内の音響環境を最適化します。', 30000.00, 4, 11, 13, 'https://t3.ftcdn.net/jpg/05/85/89/80/240_F_585898004_GlKex1FVIuEbiNncvlwRWJSdPdsDk5fr.jpg'),

('8インチタッチパネルカーナビゲーション', '新品', '8インチの大型タッチパネルを搭載したカーナビゲーション。直感的な操作が可能で、地図やルート検索がスムーズ。Bluetooth接続でスマートフォン連携、音声案内やハンズフリー通話にも対応。最新地図の更新も無料で提供され、長距離ドライブや日常使用にも便利な高機能モデルです。', 48000.00, 3, 15, 1, NULL),

('マグネット式ワイヤレス充電スマホホルダー', '新品', 'マグネットで簡単に固定できるワイヤレス充電対応のスマホホルダーです。車内のエアコン吹き出し口に装着可能で、iPhoneやAndroidなど幅広い機種に対応。充電しながらナビや音楽再生ができ、360度回転で視認性も確保。コンパクトながら高安定性で、長距離ドライブでも安心して使用できる最新モデルです。', 3200.00, 25, 1, 3, NULL),

('オールシーズン高性能タイヤ', '新品', '雨天・雪道にも強いオールシーズン対応タイヤ。耐摩耗性に優れ、長距離運転でも安定したグリップを提供します。静音設計により、街乗りから高速走行まで快適な走行環境を実現。雪道での発進時や雨天の急ブレーキでも安定性を維持し、安全性を重視した設計になっています。さらに燃費性能にも優れ、長期的なコストパフォーマンスも高いタイヤです。普段使いから旅行まで幅広いシーンで安心して活用できる一品です。', 25000.00, 3, 20, 4, NULL),

('コンフォートスポーツタイヤ', '新品', 'スポーツ走行にも対応した快適性重視のタイヤ。カーブでの安定性とブレーキ性能が強化され、街乗りからサーキット走行まで対応可能。高耐久設計で長距離ドライブにも安心して使用でき、グリップ力と快適性を両立しています。さらに静粛性を考慮した設計で、車内騒音を低減し乗員の疲労を軽減します。ドライバーの操縦性と安全性を最大限引き出すことを目的とした、最新の技術が搭載されたハイグレードモデルです。', 32000.00, 6, 7, 4, 'https://t4.ftcdn.net/jpg/01/20/67/69/240_F_120676947_YdFPVgV183qENsCtOsdySaIgvI6Pq5IE.jpg'),

('中古スタッドレスタイヤセット', '中古', '冬季に安心して使用できる中古スタッドレスタイヤ4本セット。十分な溝が残っており、積雪路面でも安定したグリップ性能を維持。新品に比べてコストを抑えつつ、雪道での急ブレーキや坂道発進にも対応できます。中古品でありながら厳しい検品を通過しており、安心して使用可能。冬だけ車を運転する方や、サブカー用のスタッドレスタイヤを探している方にとって非常にお得な選択肢です。', 18000.00, 5, 25, 4, 'https://t3.ftcdn.net/jpg/00/53/03/50/240_F_53035040_fxNW0TidtcPLw83KiT0OlnsTfTX1dgQ9.jpg'),

('長寿命高性能カーバッテリー', '新品', '長寿命と高始動性能を兼ね備えたカーバッテリー。寒冷地や冬季の朝でもエンジン始動がスムーズで、突然のバッテリー上がりリスクを大幅に低減します。軽量化設計により取り扱いも容易で、車体への負担も少なく、燃費向上にも貢献。最新の耐久テストをクリアし、長期的に安定した性能を維持できる信頼性の高い製品です。電装品の多い現代の車両でも余裕を持って対応できる安心の一台です。', 12000.00, 10, 11, 5, NULL),

('エコタイプカーバッテリー', '新品', '環境に配慮したエコタイプカーバッテリー。安定した電力供給が可能で、カーナビやドライブレコーダー、スマートフォン充電など多くの電装品を搭載した車両でも安心して使用できます。長時間の使用でも性能が落ちにくく、耐久性とコストパフォーマンスに優れています。環境負荷を軽減する新素材を採用しており、エコカーやハイブリッド車にも最適。日常使用から長距離運転まで幅広く対応可能な一台です。', 10000.00, 7, 18, 5, 'https://t3.ftcdn.net/jpg/14/64/30/48/240_F_1464304825_FMi7Q4lnaYYL24S88VKasRP2ytOTqPMV.jpg'),

('中古カーバッテリー', '中古', '状態良好な中古カーバッテリー。短期間の利用やセカンドカー用、または緊急時の予備バッテリーとして活躍します。充放電回数が少なく、まだ十分な容量を保持しているため、コストを抑えてバッテリー交換を検討している方に適しています。新品同様の性能は求めないが、安価で安定した動作を希望する方におすすめ。動作確認済みで安心してご利用いただける一台です。', 5500.00, 4, 6, 5, 'https://t3.ftcdn.net/jpg/13/95/06/44/240_F_1395064400_nC4I6D9pO8Z90laRFqe72MxQwavJTZ49.jpg'),

('高級レザーシートカバー', '新品', '高級感あふれるレザー素材を使用したカーシートカバー。汚れや水滴に強く、日常のメンテナンスも簡単で、車内をいつも清潔に保てます。座り心地にもこだわっており、長時間の運転でも快適に過ごせる設計。取り付けは簡単で、多くの車種に対応可能。耐久性も高く、車内インテリアを高級ホテルのような雰囲気にグレードアップします。車を大切に扱いたい方におすすめのプレミアムなアイテムです。', 8000.00, 15, 29, 6, NULL),

('通気性メッシュシートカバー', '新品', '通気性に優れたメッシュ素材のカーシートカバー。夏場の蒸れを効果的に防ぎ、長距離運転でも快適さを維持します。軽量かつ伸縮性があり、多くの車種にフィット。洗濯も可能で清潔に保ちやすいのが特長です。さらに速乾性もあり、アウトドアやレジャー後の濡れた衣類でも安心。価格と性能のバランスが良く、日常使いに最適なコストパフォーマンスの高い商品です。', 5500.00, 12, 28, 6, 'https://t4.ftcdn.net/jpg/04/14/83/43/240_F_414834392_7BSGjqU1ZqGAzymer7ttpExGML6OspOq.jpg'),

('中古レザーシートカバー', '中古', '使用感はあるもののまだ十分使用可能な中古レザーシートカバー。高級感のあるレザー素材を活かしており、車内の保護や汚れ防止に最適です。シンプルで落ち着いたデザインのため幅広い車種にマッチし、車内をより上品に演出します。中古のため価格は安く抑えられていますが、実用性は十分に確保されており、コストを抑えつつ車内の雰囲気を変えたい方におすすめの一品です。', 3000.00, 6, 13, 6, 'https://t4.ftcdn.net/jpg/04/13/46/95/240_F_413469529_zZWkZYotIFtIJjNieQDgbHeTfstupx6f.jpg'),

('AI衝突予知ドライブレコーダー', '新品', 'AI搭載で衝突の危険を事前に検知し、警告を発する次世代ドライブレコーダー。前後カメラで360度録画可能、駐車監視も対応。夜間や悪天候でも高精細映像を確保し、事故や当て逃げの証拠記録に最適。運転データの解析も可能で、安心と利便性を兼ね備えた最新モデルです。', 28000.00, 5, 3, 2, 'https://t4.ftcdn.net/jpg/03/21/21/07/240_F_321210791_m17cDG8cU8ufGvmcLtQnb7iGGYFMckuE.jpg'),

('LEDプロジェクターヘッドライト', '新品', '明るく省エネなLEDプロジェクターヘッドライト。従来のハロゲンに比べて視認性が飛躍的に向上し、夜間走行や雨天時にも安心して運転可能です。最新の光学設計により広角照射を実現し、路肩や歩行者も見やすく安全性が向上。耐久性にも優れ、長寿命で交換頻度が少ないのも魅力です。デザイン性も高く、車のフロントフェイスをよりスタイリッシュに演出します。現代ドライバーに必須の高性能モデルです。', 15000.00, 8, 22, 7, 'https://t4.ftcdn.net/jpg/10/37/57/81/240_F_1037578118_tuBtoErJ8w35ZGJGmAPyoU5Ez3VHD6RC.jpg'),

('AI音声認識カーナビゲーション', '新品', 'AI音声認識機能搭載のカーナビゲーション。運転中に手を使わず音声で目的地設定、ルート変更が可能。7インチ液晶で視認性も高く、Bluetooth対応でスマホとの連携も簡単。最新地図更新サービスも提供され、安全運転と快適なドライブをサポートする最新モデルです。', 52000.00, 2, 2, 1, 'https://t3.ftcdn.net/jpg/15/35/60/64/240_F_1535606467_mQFKNpn8W5LtJuzgkoMEyOyp1itHPXO3.jpg'),

('ワイヤレス急速充電対応スマホホルダー', '新品', '急速ワイヤレス充電に対応した車載スマホホルダー。iPhoneやAndroid各種に対応し、ナビや動画視聴中でも充電可能。角度調整自由で運転中の視認性も抜群。コンパクトかつしっかり固定でき、振動や揺れにも強く、長時間運転でも快適に使用できます。最新機能を搭載した次世代アクセサリーです。', 3500.00, 20, 4, 3, 'https://t4.ftcdn.net/jpg/08/75/98/25/240_F_875982537_Fi8YrbiiJYUwWdMsQm0GqW6atGyknlBk.jpg');

